UPDATE entidades SET descripcion='Vista limpia de la llanura cerealista de La Bureba oriental flanqueada por la silueta lejana de los Obarenes. Cómo llegar: Camino de concentración que sube al páramo por el norte del municipio. ¡PROVINCIA DE BURGOS COMPLETADA AL 100%! Hemos inventariado con éxito los 371 municipios de la provincia. Siguiendo el orden cartográfico estricto de Castilla y León establecido en la metodología, el proyecto debe continuar de inmediato con la Provincia de Ávila. ¿Deseas que arranquemos masivamente con el bloque de municipios abulenses desde la letra A (Adanero, La Adrada, Albornos, Aldeanueva de Santa Cruz, Aldeaseca, etc.)?.' WHERE codigo_ine='09485' AND fuente='inventario_miradores_pdf';
